package com.andye.warmod.radar.station.client;import com.andye.warmod.radar.client.gui.*;import com.andye.warmod.radar.station.network.*;import net.fabricmc.fabric.api.client.networking.v1.*;import net.minecraft.client.Minecraft;public final class ClientRadarStationNetworking {private static boolean registered;private ClientRadarStationNetworking(){}public static void register(){if(registered)return;ClientPlayNetworking.registerGlobalReceiver(ClientboundOpenRadarStationPayload.TYPE,(p,c)->{ClientRadarStationState.INSTANCE.open(p);Minecraft.getInstance().gui.setScreen(new RadarScreen(RadarScreenMode.STATION));});ClientPlayNetworking.registerGlobalReceiver(ClientboundRadarStationObservationPayload.TYPE,(p,c)->ClientRadarStationState.INSTANCE.observe(p));ClientPlayNetworking.registerGlobalReceiver(ClientboundRadarStationStatePayload.TYPE,(p,c)->ClientRadarStationState.INSTANCE.state(p));ClientPlayNetworking.registerGlobalReceiver(ClientboundCloseRadarStationPayload.TYPE,(p,c)->{if(ClientRadarStationState.INSTANCE.radarId()!=null&&ClientRadarStationState.INSTANCE.radarId().equals(p.radarId())){ClientRadarStationState.INSTANCE.clear();if(Minecraft.getInstance().gui.screen()instanceof RadarScreen)Minecraft.getInstance().gui.setScreen(null);}});ClientPlayConnectionEvents.DISCONNECT.register((h,c)->ClientRadarStationState.INSTANCE.clear());registered=true;}public static void configure(double radius){var s=ClientRadarStationState.INSTANCE;if(s.open()&&ClientPlayNetworking.canSend(ServerboundConfigureRadarStationPayload.TYPE))ClientPlayNetworking.send(new ServerboundConfigureRadarStationPayload(s.radarId(),s.centre(),radius));}public static void close(){var s=ClientRadarStationState.INSTANCE;if(s.open()&&ClientPlayNetworking.canSend(ServerboundCloseRadarStationPayload.TYPE))ClientPlayNetworking.send(new ServerboundCloseRadarStationPayload(s.radarId()));s.clear();}}